 $qualified=$facets.notExited -and $facets.retainedWaitActive -and $facets.processTimesSucceeded -and $facets.creationMatches -and $facets.dotNetStartMatches -and $facets.imagePathMatches -and $facets.mainWindowMatches -and $facets.expectedWindowVisible -and $facets.windowThreadSucceeded -and $facets.windowOwnerMatches -and $facets.imageShaMatches
