function Snapshot([string]$Tag){
 Assert-OwnNativeIdentity;$providers=Get-OwnUiaProviders;$script:providers=$providers;$s=[OwnUpdaterUia]::Capture($window.ToInt64(),[int]$native.ProcessId,[int[]]$providers.allowedPids);$script:serial++;$name=$Tag+'-'+$serial.ToString('000');$s.OriginalRowCount=$s.Rows.Count
