 Write-OwnJson ($name+'-providers.json') $providers;Write-OwnJson ($name+'.json') $s;if(!$s.Complete){throw 'Incomplete/foreign/capped UIA inventory'};$text=[OwnUpdaterUia]::VisibleText($s);if($text.Contains('The viewport could not start.') -or $text.Contains('Automatic updates are unavailable for this copy.')){throw 'Native startup/updater error'};return $s
}
