 if($state){$proof.installInvoke=$state;$proof.installInvokeRpcPending=$state.LeaseState -eq 1 -and !$state.Completed;if($state.Attempted -and $proof.actions -notcontains 'clean-install-invoke'){$proof.actions+=@('clean-install-invoke')}}
