 if(!$selected.InvokeAvailable -or !(Stock-Clean $before '0.9.5') -or $beforeText -notmatch 'Current\s+version:\s*0\.9\.5\b' -or !$beforeText.Contains('Version 0.9.6 is ready to install.')){throw 'Qualified clean Current0.9.5/Ready0.9.6 SDK Install unavailable'}
