 if(!$current.InvokeAvailable -or $current.ProcessId -ne $selected.ProcessId -or ($current.RuntimeId -join '.') -ne ($selected.RuntimeId -join '.') -or !(Stock-Clean $fresh '0.9.5') -or $text -notmatch 'Current\s+version:\s*0\.9\.5\b' -or !$text.Contains('Version 0.9.6 is ready to install.')){throw 'Same live Install RuntimeID/provider/pattern/CurrentReady changed'}
