 $proof.installActionRoute='SDK_InvokePattern_Invoke';$beginError=$null;$beginReturned=$false
 try{[OwnInstallInvoke]::Begin($window.ToInt64(),[int]$native.ProcessId,$native.Process,$created,[int[]]$providers.allowedPids,[int]$current.ProcessId,[int[]]$current.RuntimeId);$beginReturned=$true}catch{$beginError=$_.Exception.Message.Substring(0,[Math]::Min(2048,$_.Exception.Message.Length))}
 $clock=[Diagnostics.Stopwatch]::StartNew();$state=[OwnInstallInvoke]::Status()
 while($beginReturned -and $state -and $state.LeaseState -eq 0 -and !$state.Completed -and $clock.Elapsed.TotalSeconds -lt 20){Start-Sleep -Milliseconds 100;$state=[OwnInstallInvoke]::Status()}
 $cancelAttempted=$false;$canceled=$false
 if($state -and $state.LeaseState -eq 0){$cancelAttempted=$true;$canceled=[OwnInstallInvoke]::CancelPending();$state=[OwnInstallInvoke]::Status()}
 Write-OwnJson 'clean-install-invoke-dispatch.json' ([ordered]@{beginReturned=$beginReturned;beginError=$beginError;state=$state;elapsedMilliseconds=$clock.ElapsedMilliseconds;waitLimitSeconds=20;workerPreflightBudgetSeconds=15;cancelPendingAttempted=$cancelAttempted;cancelPendingWon=$canceled;noLateDispatchAfterPendingCancellation=$true;noFallback=$true})
 $state=Observe-InstallInvoke 'clean-install-invoke-result'
 if(!$state -or $state.LeaseState -ne 1){throw 'SDK Install never committed an invocation; pending lease canceled and no alternate action'}
